import {today,minuteLabel,escapeHTML as h,statusNames} from './domain.js';
import {icon} from './icons.js';
import {availableStart,studentCardFormat,requestIdentity} from './booker-domain.js';
import {TERMS_OF_SERVICE_TEXT,PRIVACY_POLICY_TEXT} from './legal.js';
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const cfg=window.CONNECT_CONFIG;
const db=cfg?.url&&cfg?.key?window.supabase.createClient(cfg.url,cfg.key,{auth:{storageKey:'connect-owner-web-auth',detectSessionInUrl:false}}):null;
const s={user:null,profile:null,verification:null,page:'search',stores:[],reservations:[],store:null,slots:[],day:today(),people:2,count:3,start:null,region:'',category:'',ready:false,busy:false,error:'',notice:'',email:'',sent:false,signup:false,cooldown:0,epoch:0,loaded:false,edit:null,identity:null};
const button=(label,action,cls='',extra='')=>`<button type="button" data-b="${action}" class="${cls}" ${extra}>${label}</button>`;
const field=(label,name,value='',extra='')=>`<label class="field">${label}<input name="${name}" value="${h(value)}" ${extra}></label>`;
const stateLabel={draft:'미제출',pending:'심사 중',approved:'승인 완료',rejected:'재신청 필요'};
const approved=()=>s.verification?.status==='approved';
const authError=e=>e?.message||'연결하지 못했습니다. 잠시 후 다시 시도해주세요.';
async function result(query){const {data,error}=await query;if(error)throw error;return data;}
async function rpc(name,args){if(!db)throw Error('서버 연결 설정을 확인해주세요.');return result(db.rpc(name,args));}
function message(){return `<div id="booker-feedback" aria-live="polite">${s.error?`<p class="notice error" role="alert">${h(s.error)}</p>`:''}${s.notice?`<p class="notice">${h(s.notice)}</p>`:''}</div>`;}
function showMessage(){const e=document.querySelector('#booker-feedback');if(e)e.outerHTML=message();}
function setBusy(value){s.busy=value;root.setAttribute('aria-busy',String(value));for(const el of root.querySelectorAll('button,input,select,textarea')){if(value){el.dataset.wasDisabled=String(el.disabled);el.disabled=true;}else{el.disabled=el.dataset.wasDisabled==='true';delete el.dataset.wasDisabled;}}}
async function run(fn){if(s.busy)return;const epoch=s.epoch;setBusy(true);s.error='';s.notice='';showMessage();try{await fn();}catch(e){if(epoch===s.epoch){s.error=authError(e);showMessage();}}finally{if(epoch===s.epoch)setBusy(false);}}
function shell(content){root.innerHTML=`<header class="topbar"><a class="brand" href="./"><span class="brand-mark">c</span>Connect</a><nav class="booker-nav" aria-label="예약자 메뉴">${button('매장 찾기','search',s.page==='search'?'active':'')}${button('내 예약','reservations',s.page==='reservations'?'active':'')}${button('학생증 인증','verify',s.page==='verify'?'active':'')}</nav><div class="top-actions">${button(icon('moon'),'theme','theme-toggle','aria-label="화면 테마 전환"')}${s.user?button('로그아웃','logout','ghost'):button('로그인 / 가입','login','primary')}</div></header><main class="booker-workspace">${message()}${content}</main><footer class="booker-footer">Connect · 모임을 연결하다 <a href="./">이용 유형 선택</a><span>시간은 한국 표준시 기준입니다.</span></footer>`;if(s.busy)setBusy(true);}
function render(){
 if(!s.ready)return shell('<p class="empty">계정을 확인하고 있습니다…</p>');
 if(s.profile&&s.profile.role!=='booker')return shell('<section class="panel booker-auth"><h1>점주 계정으로 로그인되어 있어요</h1><p>현재 계정은 점주용입니다. 예약자는 별도의 예약자 계정으로 로그인해주세요.</p><a class="button-link primary" href="?role=owner">점주 화면으로 이동</a></section>');
 if(s.user&&!s.profile&&!s.loaded)return shell(`<section class="panel booker-auth"><h1>계정 정보를 불러오지 못했어요</h1>${button('다시 연결','refresh')}</section>`);
 if(s.user&&!s.profile)return shell(profileForm());
 if(s.page==='login')return shell(loginForm());
 if(s.page==='verify')return shell(verificationView());
 if(s.page==='reservations')return shell(reservationsView());
 if(s.page==='detail'&&s.store)return shell(detailView());
 shell(searchView());
}
function loginForm(){return `<section class="panel booker-auth"><p class="eyebrow">WELCOME TO CONNECT</p><h1>예약자 ${s.signup?'회원가입':'로그인'}</h1><p class="muted">앱과 동일한 이메일로 이용하세요.<br>일반 이메일로 가입하고, 학생증 승인 후 예약할 수 있어요.</p><form id="b-auth">${field('이메일','email',s.email,`type="email" autocomplete="email" required ${s.sent?'readonly':''}`)}${s.sent?field('인증번호','token','', 'inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" required'):''}<button class="primary">${s.sent?'인증하고 계속':'인증번호 받기'}</button></form>${s.sent?button('이메일 변경 / 재요청','reset-code','ghost'):button(s.signup?'이미 가입했나요? 로그인':'처음인가요? 회원가입','signup','ghost')}<p class="form-note">메일함과 스팸함을 확인해주세요. 인증 메일 재요청은 60초 후 가능합니다.</p></section>`;}
function profileForm(){return `<section class="panel booker-auth"><p class="eyebrow">ONE MORE STEP</p><h1>예약자 정보를 알려주세요</h1><p class="muted">이메일 인증 완료 · ${h(s.user.email)}<br>이름은 모든 예약의 대표 예약자명으로 사용됩니다.</p><form id="b-profile">${field('대표 예약자명 (필수)','name','','required maxlength="80" autocomplete="name"')}${field('학교명 (필수)','school','','required maxlength="100"')}${field('학과 / 단체명 (선택)','department','','maxlength="160"')}${field('직책 (선택)','position','','maxlength="80"')}<details><summary>이용약관 보기 (초안)</summary><pre class="legal-copy">${h(TERMS_OF_SERVICE_TEXT)}</pre></details><label class="check-label"><input type="checkbox" name="terms" required>이용약관 동의 (필수)</label><details><summary>개인정보 수집·이용 안내 보기 (초안)</summary><pre class="legal-copy">${h(PRIVACY_POLICY_TEXT)}</pre></details><label class="check-label"><input type="checkbox" name="privacy" required>개인정보 수집·이용 동의 (필수)</label><button class="primary">가입 완료하기</button></form></section>`;}
function searchView(){return `<section class="booker-hero"><p class="eyebrow">A PLACE FOR EVERY GATHERING</p><h1>우리 모임에 딱 맞는 공간.</h1><p>날짜와 인원을 정하면, 함께할 자리가 보입니다.</p></section><section class="panel search-panel"><form id="b-search" class="search-form">${field('언제 모이나요?','date',s.day,`type="date" min="${today()}" required`)}${field('몇 명인가요?','people',s.people,'type="number" min="1" max="10000" required')}${field('지역','region',s.region,'placeholder="전체 지역" maxlength="40"')}${field('업종','category',s.category,'placeholder="전체 업종" maxlength="40"')}<label class="field">이용 시간<select name="count">${durationOptions()}</select></label><button class="primary">매장 찾기 →</button></form></section><div class="heading booker-results"><div><h2>예약 가능한 매장 <span class="muted">${s.stores.length}</span></h2><p>${h(s.day)} · ${s.people}명 · ${s.count*30}분 기준</p></div><span class="small muted">예약 신청 후 점주가 확정합니다</span></div><div class="store-grid">${s.stores.map(store=>`<article class="panel store-card"><div class="store-art">${icon('calendar')}<span>${h(store.category)}</span></div><div class="store-copy"><span class="eyebrow">${h(store.region)}</span><h2>${h(store.name)}</h2><p class="muted">${h(store.description||'함께할 모임의 자리를 확인해보세요.')}</p><div class="store-meta"><span>최대 ${store.capacity}명</span><span>${minuteLabel(store.opening_minute)}–${minuteLabel(store.closing_minute)}</span></div>${button('매장 상세 · 시간 선택 →','store','',`data-id="${h(store.id)}"`)}</div></article>`).join('')||'<section class="panel empty">조건에 맞는 매장이 없습니다.<br>다른 날짜나 인원으로 검색해보세요.</section>'}</div>`;}
function durationOptions(){return [1,2,3,4,5,6].map(n=>`<option value="${n}" ${s.count===n?'selected':''}>${n*30}분</option>`).join('');}
function detailView(){const store=s.store;return `${button('← 매장 목록','search','ghost')}<div class="booker-detail"><section><div class="store-art detail-art">${icon('calendar')}<span>${h(store.region)} · ${h(store.category)}</span></div><p class="eyebrow">LET'S GET TOGETHER</p><h1>${h(store.name)}</h1><p class="muted">${h(store.description||'매장의 예약 가능 시간을 확인하고 모임을 신청하세요.')}</p><div class="store-meta"><span>최대 ${store.capacity}명</span><span>${store.allow_shared?'다른 모임과 함께 이용 가능':'한 번에 한 팀 이용'}</span></div><p class="muted">영업시간 ${minuteLabel(store.opening_minute)}–${minuteLabel(store.closing_minute)}</p><div class="panel detail-note"><h3>예약 전 확인해주세요</h3><p>신청한 예약은 점주 승인 후 확정됩니다.</p><p>확정 예약을 변경하면 다시 승인 대기로 전환됩니다.</p><p>‘다음 날’ 시간은 선택한 영업일의 자정 이후입니다.</p></div></section><section class="panel booking-panel"><h2>${s.edit?'예약 변경':'모임 예약하기'}</h2>${s.edit?'<p class="notice">저장하면 기존 확정 좌석이 해제되고 점주의 재승인을 받습니다.</p>':''}<form id="b-booking"><div class="form-grid">${field('영업일','date',s.day,`type="date" min="${today()}" required`)}${field('인원','people',s.people,`type="number" min="1" max="${store.capacity}" required`)}<label class="field">이용 시간<select name="count">${durationOptions()}</select></label>${field('1인당 예산 (선택)','budget',s.edit?.budget_per_person??'','type="number" min="0" max="10000000"')}</div><div><h3>시작 시간</h3><p class="form-note">선택한 ${s.count*30}분 동안 이용 가능한 시간입니다.</p><div class="booker-times">${s.slots.map(slot=>{const ok=availableStart(s.slots,slot.start_minute,s.count,s.people,s.day);return button(`${minuteLabel(slot.start_minute)}<small>${ok?`잔여 ${slot.remaining_seats}석`:'예약 불가'}`,'time',s.start===slot.start_minute?'primary':'',`data-minute="${slot.start_minute}" aria-pressed="${s.start===slot.start_minute}" ${ok?'':'disabled'}`).replace('</button>','</small></button>');}).join('')||'<p class="empty">표시할 시간이 없습니다.</p>'}</div></div>${field('모임 목적 (선택)','purpose',s.edit?.event_purpose??'','maxlength="30" placeholder="예: 동아리 회식"')}<label class="field">요청사항 (선택)<textarea name="request" maxlength="1000" placeholder="매장에 전달할 내용을 적어주세요">${h(s.edit?.request_message||'')}</textarea></label><p class="form-note">대표 예약자: ${h(s.profile?.real_name||'로그인 후 확인')}<br>소속: ${h([s.profile?.school_name,s.profile?.department_name].filter(Boolean).join(' ')||'가입 정보 기준')}</p>${!s.user?button('로그인하고 예약하기','login','primary'):!approved()?button('학생증 인증하고 예약하기','verify','primary'):`<button class="primary" ${s.start===null?'disabled':''}>${s.edit?'변경하고 재승인 요청':'예약 신청하기'}</button>`}${s.edit?button('변경 취소','reservations','ghost'):''}</form></section></div>`;}
function verificationView(){if(!s.user)return loginForm();const v=s.verification;return `<section class="panel booker-auth"><p class="eyebrow">STUDENT VERIFICATION</p><h1>학생증 인증</h1><span class="tag ${v?.status==='approved'?'confirmed':'pending'}">${stateLabel[v?.status]||'인증 필요'}</span><p>${h(s.profile.real_name)} · ${h(s.profile.school_name)}</p><p class="muted">이름과 학교명이 보이는 학생증을 제출해주세요. 관리자가 확인한 뒤 예약을 이용할 수 있습니다.</p>${v?.rejection_reason?`<p class="notice error">반려 사유: ${h(v.rejection_reason)}</p>`:''}${['approved','pending'].includes(v?.status)?`<p class="notice">${v.status==='approved'?'인증이 완료되었습니다. 원하는 매장을 예약해보세요.':'제출이 완료되었습니다. 심사가 끝나면 상태가 변경됩니다.'}</p>`:`<form id="b-verification"><label class="field">학생증 파일 (JPG · PNG · PDF, 최대 10MB)<input type="file" name="card" accept="image/jpeg,image/png,application/pdf" required></label><p class="form-note">학생증은 비공개로 저장되며 본인과 심사 관리자만 접근할 수 있습니다. 불필요한 학번·생년월일 등은 가린 뒤 제출해주세요.</p><label class="check-label"><input type="checkbox" required>학생 확인을 위한 서류 제출에 동의합니다.</label><button class="primary">학생증 제출하기</button></form>${v?.status==='draft'?button('업로드된 서류 제출 재시도','submit-card','ghost'):''}`}${button('심사 상태 새로고침','refresh','ghost')}</section>`;}
function reservationsView(){if(!s.user)return loginForm();return `<div class="heading"><div><p class="eyebrow">YOUR GATHERINGS</p><h1>내 예약</h1><p>앱에서 신청한 예약도 함께 확인하세요.</p></div>${button('새로고침','refresh')}</div><div class="reservation-list">${s.reservations.map(r=>`<article class="panel reservation-card"><div><span class="tag ${h(r.status)}">${h(statusNames[r.status]||r.status)}</span><h2>${h(r.stores?.name||'매장')}</h2><p>${h(r.service_date)} · ${minuteLabel(r.start_minute)}–${minuteLabel(r.start_minute+r.slot_count*30)} · ${r.people}명</p><p class="small muted">대표 ${h(r.booker_name)}${r.booker_affiliation?` · ${h(r.booker_affiliation)}`:''}</p>${r.event_purpose?`<p>${h(r.event_purpose)}</p>`:''}${r.request_message?`<p class="memo">${h(r.request_message)}</p>`:''}</div><div class="inline">${['pending','confirmed'].includes(r.status)&&new Date(r.starts_at)>new Date()?`${button('예약 변경','edit','',`data-id="${h(r.id)}"`)}${button('예약 취소','cancel','danger',`data-id="${h(r.id)}"`)}`:''}</div></article>`).join('')||'<section class="panel empty">아직 신청한 예약이 없습니다.<br>마음에 드는 매장을 찾아 첫 모임을 준비해보세요.</section>'}</div>`;}
async function account(){const epoch=s.epoch;if(!s.user){s.loaded=true;return;}const profile=await result(db.from('profiles').select('*').eq('id',s.user.id).maybeSingle());if(epoch!==s.epoch)return;s.profile=profile;s.loaded=true;if(profile?.role==='booker'){const verification=await result(db.from('student_verifications').select('*').eq('user_id',s.user.id).maybeSingle());if(epoch===s.epoch)s.verification=verification;}}
async function search(){const epoch=s.epoch;const stores=await rpc('search_stores',{p_region:s.region||null,p_category:s.category||null,p_service_date:s.day,p_people:s.people,p_slot_count:s.count});if(epoch===s.epoch)s.stores=stores||[];}
async function reservations(){if(!s.user)return;const epoch=s.epoch;const rows=[];for(let offset=0;;offset+=500){const chunk=await result(db.from('reservations').select('*, stores(name)').eq('booker_id',s.user.id).order('service_date',{ascending:false}).order('start_minute',{ascending:false}).order('id').range(offset,offset+499));if(epoch!==s.epoch)return;rows.push(...chunk);if(chunk.length<500)break;}s.reservations=rows;}
async function availability(){const epoch=s.epoch;const slots=await rpc('get_availability',{p_store_id:s.store.id,p_service_date:s.day});if(epoch===s.epoch){s.slots=(slots||[]).map(slot=>{if(s.edit?.status==='confirmed'){const at=new Date(s.day+'T00:00:00+09:00').getTime()+slot.start_minute*60000;if(at<new Date(s.edit.ends_at).getTime()&&at+1800000>new Date(s.edit.starts_at).getTime()&&!slot.blocked)return {...slot,remaining_seats:s.store.allow_shared?Math.min(s.store.capacity,slot.remaining_seats+s.edit.people):s.store.capacity};}return slot;});if(!availableStart(s.slots,s.start,s.count,s.people,s.day))s.start=null;}}
async function navigate(page){s.error='';s.notice='';s.page=page;s.edit=null;if(page==='reservations'){if(!s.user){s.page='login';}else await reservations();}if(page==='verify'){if(!s.user)s.page='login';else await account();}if(page==='search')await search();render();}
async function refresh(){await account();if(s.page==='reservations')await reservations();if(s.page==='detail')await availability();if(s.page==='search')await search();render();}
async function checkAccount(id){const {data,error}=await db.auth.getSession();if(error)throw error;if(data.session?.user.id!==id)throw Error('로그인 계정이 변경되었습니다. 다시 시도해주세요.');}
root.addEventListener('click',e=>{const el=e.target.closest('[data-b]');if(!el||s.busy)return;const action=el.dataset.b;if(action==='theme'){window.connectTheme.toggle();return;}run(async()=>{
 if(['search','reservations','verify','login'].includes(action)){await navigate(action);return;}
 if(action==='refresh'){await refresh();return;}
 if(action==='signup'){s.signup=!s.signup;s.sent=false;render();return;}
 if(action==='reset-code'){if(Date.now()<s.cooldown)throw Error('인증 메일은 60초 후 다시 요청할 수 있습니다.');s.sent=false;render();return;}
 if(action==='logout'){await result(db.auth.signOut());return;}
 if(action==='store'){s.store=s.stores.find(x=>x.id===el.dataset.id);s.edit=null;s.start=null;s.identity=null;await availability();s.page='detail';render();return;}
 if(action==='time'){s.start=Number(el.dataset.minute);for(const b of root.querySelectorAll('[data-b=time]')){const selected=Number(b.dataset.minute)===s.start;b.classList.toggle('primary',selected);b.setAttribute('aria-pressed',String(selected));}const submit=root.querySelector('#b-booking button:not([type])');if(submit){submit.disabled=false;submit.dataset.wasDisabled='false';}return;}
 if(action==='edit'){const r=s.reservations.find(x=>x.id===el.dataset.id);if(!approved())throw Error('학생증 승인 후 예약을 변경할 수 있습니다.');s.store=await result(db.from('stores').select('*').eq('id',r.store_id).single());s.edit=r;s.day=r.service_date;s.people=r.people;s.count=r.slot_count;s.start=r.start_minute;await availability();s.page='detail';render();return;}
 if(action==='cancel'){modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">예약을 취소할까요?</h2></div><div class="modal-body"><p>취소 후에는 다시 예약을 신청해야 합니다.</p><p class="form-error" role="alert"></p><div class="modal-footer"><button id="cancel-back">돌아가기</button><button id="cancel-confirm" class="danger">예약 취소</button></div></div>`;modal.showModal();document.querySelector('#cancel-back').onclick=()=>modal.close();document.querySelector('#cancel-confirm').onclick=async()=>{const b=document.querySelector('#cancel-confirm');b.disabled=true;try{await rpc('cancel_reservation',{p_reservation_id:el.dataset.id});modal.close();await run(async()=>{await reservations();s.notice='예약이 취소되었습니다.';render();});}catch(err){modal.querySelector('[role=alert]').textContent=authError(err);}finally{b.disabled=false;}};return;}
 if(action==='submit-card'){await rpc('submit_student_verification',{p_request_id:s.verification.request_id});await account();s.notice='심사를 요청했습니다.';render();}
});});
root.addEventListener('change',e=>{if(!e.target.closest('#b-booking')||!['date','people','count'].includes(e.target.name))return;const f=e.target.form;if(!f.elements.date.checkValidity()||!f.elements.people.checkValidity())return;const draft={purpose:f.elements.purpose.value,request:f.elements.request.value,budget:f.elements.budget.value};run(async()=>{s.day=f.elements.date.value;s.people=Number(f.elements.people.value);s.count=Number(f.elements.count.value);s.start=null;await availability();render();const n=root.querySelector('#b-booking');for(const [key,value]of Object.entries(draft))n.elements[key].value=value;});});
root.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f),v=k=>String(fd.get(k)||'').trim();run(async()=>{
 if(f.id==='b-auth'){if(!db)throw Error('서버 연결 설정이 없습니다.');if(!s.sent){if(Date.now()<s.cooldown)throw Error('잠시 후 인증 메일을 다시 요청해주세요.');s.email=v('email').toLowerCase();await result(db.auth.signInWithOtp({email:s.email,options:{shouldCreateUser:s.signup}}));s.cooldown=Date.now()+60000;s.sent=true;s.notice='인증 메일을 요청했습니다. 메일함을 확인해주세요.';render();}else{await result(db.auth.verifyOtp({email:s.email,token:v('token'),type:'email'}));}return;}
 if(f.id==='b-profile'){if(!v('name')||!v('school')||!fd.has('terms')||!fd.has('privacy'))throw Error('대표 예약자명, 학교명, 필수 동의를 확인해주세요.');await rpc('complete_profile',{p_role:'booker',p_real_name:v('name'),p_school_name:v('school'),p_department_name:v('department'),p_position:v('position')});await account();s.page='verify';render();return;}
 if(f.id==='b-search'){s.day=v('date');s.people=Number(v('people'));s.count=Number(v('count'));s.region=v('region');s.category=v('category');await search();render();return;}
 if(f.id==='b-booking'){if(!approved())throw Error('학생증 승인 후 예약할 수 있습니다.');if(!availableStart(s.slots,s.start,s.count,s.people,s.day))throw Error('예약 가능한 시작 시간을 선택해주세요.');const payload={p_service_date:s.day,p_start_minute:s.start,p_slot_count:s.count,p_people:s.people,p_budget_per_person:v('budget')?Number(v('budget')):null,p_event_purpose:v('purpose'),p_request_message:v('request')};if(s.edit){await rpc('edit_reservation',{...payload,p_reservation_id:s.edit.id});}else{payload.p_store_id=s.store.id;s.identity=requestIdentity(s.identity,payload);await rpc('request_reservation',{...payload,p_request_id:s.identity.id});}s.identity=null;s.edit=null;s.page='reservations';s.notice='예약 요청을 보냈습니다. 점주 승인 후 확정됩니다.';await reservations();render();return;}
 if(f.id==='b-verification'){const file=fd.get('card');if(!file?.size||file.size>10*1024*1024)throw Error('10MB 이하 학생증 파일을 선택해주세요.');const bytes=await file.arrayBuffer(),format=studentCardFormat(bytes),id=s.user.id;await checkAccount(id);const previous=s.verification;if(previous&&['draft','rejected'].includes(previous.status))await result(db.storage.from('student-cards').remove([previous.document_path]));await checkAccount(id);const draft=await rpc('begin_student_verification',{p_extension:format.extension});s.verification=draft;await checkAccount(id);await result(db.storage.from('student-cards').upload(draft.document_path,bytes,{contentType:format.contentType,upsert:false,cacheControl:'0'}));await checkAccount(id);await rpc('submit_student_verification',{p_request_id:draft.request_id});await account();s.notice='학생증을 제출했습니다. 심사 결과를 기다려주세요.';render();}
});});
async function sessionChanged(session){const next=session?.user||null;if(s.ready&&next?.id===s.user?.id)return;s.epoch++;s.busy=false;Object.assign(s,{user:next,profile:null,verification:null,reservations:[],loaded:false,error:'',notice:'',ready:false,edit:null,identity:null});if(modal.open)modal.close();render();try{await account();s.ready=true;s.page=next?'search':s.page==='login'?'login':'search';await search();}catch(e){s.error=authError(e);s.ready=true;}render();}
if(db){db.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>sessionChanged(session),0);});}else{s.ready=true;s.error='서버 연결 설정이 없습니다.';render();}
window.addEventListener('online',()=>{if(s.ready&&!s.busy)run(refresh);});
window.addEventListener('focus',()=>{if(s.ready&&s.user&&!s.busy&&(s.page==='reservations'||s.page==='verify'&&['pending','approved'].includes(s.verification?.status)))run(refresh);});
setInterval(()=>{if(!document.hidden&&s.ready&&s.user&&!s.busy&&(s.page==='reservations'||s.page==='verify'&&['pending','approved'].includes(s.verification?.status)))run(refresh);},15000);
render();
